// Deterministic native A/V test: delay only audio, seek while buffering, pause,
// release the connection, switch quality/audio, then return to a local file.
// Fixtures are generated by FFmpeg into the OS temporary directory.
import { createServer } from "node:http";
import { readFile, mkdir } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { execFileSync } from "node:child_process";
import assert from "node:assert/strict";
import { connectPlayer } from "./cdp-connection.mjs";

const directory = join(tmpdir(), "lingo-network-fixtures");
await mkdir(directory, { recursive: true });
const ffmpeg = join(process.cwd(), "src-tauri", "binaries", "ffmpeg.exe");
try { await readFile(join(directory, "video.mp4")); } catch {
  execFileSync(ffmpeg, ["-hide_banner", "-loglevel", "error", "-y", "-f", "lavfi", "-i", "testsrc2=size=640x360:rate=30", "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000", "-t", "90", "-c:v", "libx264", "-preset", "ultrafast", "-crf", "24", "-pix_fmt", "yuv420p", "-c:a", "aac", "-movflags", "+faststart", join(directory, "muxed.mp4")], { windowsHide: true });
  execFileSync(ffmpeg, ["-hide_banner", "-loglevel", "error", "-y", "-i", join(directory, "muxed.mp4"), "-an", "-c:v", "copy", "-movflags", "+faststart", join(directory, "video.mp4"), "-vn", "-c:a", "copy", "-movflags", "+faststart", join(directory, "audio.m4a")], { windowsHide: true });
}
const [videoBytes, audioBytes] = await Promise.all([readFile(join(directory, "video.mp4")), readFile(join(directory, "audio.m4a"))]);
let holdAudio = false;
let delayedAudio = 0;
const sockets = new Set();
const server = createServer((request, response) => {
  const audio = request.url.startsWith("/audio");
  const bytes = audio ? audioBytes : videoBytes;
  const range = /^bytes=(\d+)-(\d*)$/.exec(request.headers.range || "");
  const start = range ? Number(range[1]) : 0;
  const end = range?.[2] ? Math.min(Number(range[2]), bytes.length - 1) : bytes.length - 1;
  if (start > end) { response.writeHead(416); response.end(); return; }
  response.writeHead(range ? 206 : 200, {
    "Accept-Ranges": "bytes", "Content-Length": end - start + 1,
    "Content-Type": audio ? "audio/mp4" : "video/mp4",
    ...(range ? { "Content-Range": `bytes ${start}-${end}/${bytes.length}` } : {})
  });
  if (request.method === "HEAD") { response.end(); return; }
  let position = start, timer;
  const write = () => {
    if (response.destroyed) return;
    if (audio && holdAudio) { delayedAudio++; timer = setTimeout(write, 80); return; }
    if (position > end) { response.end(); return; }
    // Audio cannot preload the entire fixture before the fault is injected.
    const next = Math.min(end + 1, position + (audio ? 4096 : 65536));
    const ready = response.write(bytes.subarray(position, next));
    position = next;
    if (ready) timer = setTimeout(write, audio ? 80 : 12);
    else response.once("drain", () => { timer = setTimeout(write, 12); });
  };
  response.on("close", () => clearTimeout(timer));
  write();
});
server.on("connection", (socket) => { sockets.add(socket); socket.on("close", () => sockets.delete(socket)); });
await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const base = `http://127.0.0.1:${server.address().port}`;
const player = await connectPlayer();
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const snapshot = () => player.evaluate("window.__LINGO_YOUTUBE_TEST__.snapshot()");
const wait = async (test, label, timeout = 30000) => {
  const start = Date.now();
  while (!await test()) {
    if (Date.now() - start > timeout) throw new Error(`${label}: ${JSON.stringify(await snapshot())}`);
    await sleep(100);
  }
};
const stable = (s) => s.native?.fileLoaded && s.native.firstFrameAt && !s.native.seeking && !s.native.pausedForCache;
try {
  await player.reload();
  const media = {
    videoId: "network-fixture", title: "Network synchronization test", duration: 90,
    webpageUrl: "https://www.youtube.com/watch?v=network-fixture", subtitles: [],
    audioTracks: [
      { id: "a", label: "Original", language: "en", isDefault: true, proxyUrl: base + "/audio-a" },
      { id: "b", label: "Alternate", language: "fr", proxyUrl: base + "/audio-b" }
    ],
    formats: [0, 1].map((id) => ({ id: String(id), label: `Test ${id}`, extension: "mp4", width: 640, height: 360, hasEmbeddedAudio: false, proxyUrl: base + "/video-" + id, audioProxyUrl: base + "/audio-a" }))
  };
  await player.evaluate(`window.__LINGO_YOUTUBE_TEST__.openMedia(${JSON.stringify(media)})`);
  await wait(async () => stable(await snapshot()), "fixture startup");
  await sleep(1200);
  await player.evaluate(`window.__LINGO_YOUTUBE_TEST__.openMedia(${JSON.stringify(media)})`);
  await wait(async () => stable(await snapshot()), "same-video reload");
  await sleep(1200);
  const sameVideoReload = await snapshot();
  const sameVideoAid = await player.evaluate('window.__LINGO_YOUTUBE_TEST__.nativeProperty("aid", "string")');
  const sameVideoExternalAudio = await player.evaluate('(async()=>{const y=window.__LINGO_YOUTUBE_TEST__;const n=await y.nativeProperty("track-list/count","int64");for(let i=0;i<n;i++){if(await y.nativeProperty(`track-list/${i}/type`,"string")==="audio")return y.nativeProperty(`track-list/${i}/external-filename`,"string");}return "";})()');
  assert(sameVideoReload.currentTime > .5 && !sameVideoReload.paused, "Reopening the same YouTube video must keep playing");
  assert(sameVideoAid && sameVideoAid !== "no" && sameVideoAid !== "auto", "Reopening the same YouTube video must select audio");
  assert(sameVideoExternalAudio.endsWith("/audio-a"), "Reopening the same YouTube video must attach its audio stream again");
  holdAudio = true;
  await player.evaluate("window.__LINGO_YOUTUBE_TEST__.seek(75)");
  await wait(async () => (await snapshot()).native.pausedForCache || (await snapshot()).native.seeking, "audio-only stall");
  await sleep(1200);
  const stopped = await snapshot();
  await sleep(1700);
  const stillStopped = await snapshot();
  assert(Math.abs(stillStopped.currentTime - stopped.currentTime) < .2, "Video must not run ahead while audio is unavailable");
  assert(delayedAudio > 0, "The test must actually withhold audio bytes");
  await player.evaluate("window.__LINGO_YOUTUBE_TEST__.pause()");
  holdAudio = false;
  await wait(async () => stable(await snapshot()), "audio release while user paused");
  assert((await snapshot()).paused && !(await snapshot()).playbackWanted, "Buffer completion must not override user Pause");
  await player.evaluate("window.__LINGO_YOUTUBE_TEST__.play()");
  await sleep(1200);
  const resumed = await snapshot();
  assert(resumed.currentTime > 75.5 && Math.abs(resumed.native.avSync) < .15, "Playback must resume in sync");
  const beforeAudioSwitch = resumed.currentTime;
  await player.evaluate('window.__LINGO_NATIVE_TEST__.selectAudioTrack("b")');
  await wait(async () => stable(await snapshot()), "alternate audio");
  assert.equal((await snapshot()).selectedAudioTrackId, "b");
  assert(Math.abs((await snapshot()).currentTime - beforeAudioSwitch) < 2, "Audio change must preserve time");
  const externalAudio = await player.evaluate('(async()=>{const y=window.__LINGO_YOUTUBE_TEST__;const n=await y.nativeProperty("track-list/count","int64");for(let i=0;i<n;i++){if(await y.nativeProperty(`track-list/${i}/type`,"string")==="audio")return y.nativeProperty(`track-list/${i}/external-filename`,"string");}})()');
  assert(externalAudio.endsWith("/audio-b"), "mpv must actually use the selected stream");
  await player.evaluate('window.__LINGO_YOUTUBE_TEST__.switchFormat(1)');
  await wait(async () => stable(await snapshot()), "quality change with alternate audio");
  assert.equal((await snapshot()).selectedAudioTrackId, "b");
  await player.evaluate('window.__LINGO_YOUTUBE_TEST__.switchFormat(0); document.querySelector(\'[title="Play / Pause (Space)"]\').click()');
  await wait(async () => stable(await snapshot()), "Pause click during quality load");
  assert((await snapshot()).paused && !(await snapshot()).playbackWanted, "Pause during source loading must survive file-loaded");
  await player.evaluate('window.__LINGO_YOUTUBE_TEST__.switchFormat(1); document.querySelector(\'[title="Play / Pause (Space)"]\').click()');
  await wait(async () => stable(await snapshot()) && !(await snapshot()).paused, "Play click during quality load");
  await player.evaluate(`window.__LINGO_NATIVE_TEST__.open(${JSON.stringify(join(directory, "muxed.mp4"))})`);
  await wait(async () => (await player.evaluate("window.__LINGO_NATIVE_TEST__.snapshot()")).fileLoaded, "local playback after YouTube");
  const localOptions = await player.evaluate('(async()=>{const y=window.__LINGO_YOUTUBE_TEST__;return {pause:await y.nativeProperty("options/cache-pause","flag"),audio:await y.nativeProperty("options/audio-files","string")};})()');
  assert.equal(localOptions.pause, false, "YouTube cache options must not leak into local playback");
  assert.equal(localOptions.audio, "", "YouTube audio must not leak into local playback");
  console.log(JSON.stringify({ sameVideoReloadHasAudio: true, audioOnlyStallStoppedVideo: true, pauseDuringStall: true, resumedAvDrift: resumed.native.avSync, alternateAudio: true, qualityPreservesAudio: true, playPauseDuringLoad: true, localOptionsRestored: true }, null, 2));
} finally {
  holdAudio = false;
  await player.evaluate("window.__LINGO_NATIVE_TEST__.pause()").catch(() => {});
  player.close();
  for (const socket of sockets) socket.destroy();
  server.close();
}
